-- Scoped to those two sections deliberately: penalties_related cards are
-- legitimately body-only, and a first draft of this assertion swept in
-- ten of them and failed on content that was perfectly correct.
-- ASSERT: SELECT count(*) FROM deep_dive_card_translations t JOIN deep_dive_cards d ON d.id = t.card_id JOIN countries c ON c.id = d.country_id WHERE c.name_en IN ('Denmark','Peru','Saudi Arabia') AND d.section IN ('file_format','scope_transmission') AND (t.rows_json IS NULL OR json_array_length(t.rows_json) = 0) = 0
-- And no note left in fewer than four languages, anywhere in the corpus.
-- ASSERT ALWAYS: SELECT count(*) FROM (SELECT t.card_id FROM deep_dive_card_translations t JOIN deep_dive_cards d ON d.id = t.card_id WHERE d.section = 'file_format' AND t.note IS NOT NULL AND t.note <> '' GROUP BY t.card_id HAVING count(*) <> 4) = 0
